WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY amount DESC NULLS LAST, id) AS rn FROM transactions QUALIFY rn = 1), with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_burst FROM deduped), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), enriched AS (SELECT a.id, a.account_id, a.txn_type, a.txn_time, a.merchant, a.rn, p2.opened_date, p2.balance, p2.status FROM islands a INNER JOIN accounts p2 ON a.account_id = p2.id WHERE p2.account_type = 'CREDIT'), gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM enriched), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps), deduped_transactions AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_id, txn_type ORDER BY balance DESC, id) AS latest_rank FROM sessions_transactions) x WHERE latest_rank = 1) SELECT id, account_id, txn_type, merchant, opened_date, balance, status, session_start_flag, island_id, latest_rank, SUM(session_start_flag) OVER (PARTITION BY txn_type, status ORDER BY latest_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_session_start_flag, NTILE(10) OVER (ORDER BY session_start_flag, id) session_start_flag_bucket FROM deduped_transactions;
